export interface ValheimBasics { name: string; world: string; password: string; port: number; crossplay: boolean }
const q = (s: string) => `"${s.replace(/["\\$`]/g, "")}"`;

export function valheimArgs(values: GenValues, basics: ValheimBasics): string {
  const out = [`-name ${q(basics.name || "My Server")}`, `-port ${basics.port || 2456}`, `-world ${q(basics.world || "Dedicated")}`, `-password ${q(basics.password || "change-me")}`];
  if (basics.crossplay) out.push("-crossplay");
  const preset = cleanValue(VALHEIM_FIELDS[0], values.preset ?? "normal");
  if (preset !== "normal") out.push(`-preset ${preset}`);
  for (const f of VALHEIM_FIELDS.slice(1, 6)) {
    const v = String(cleanValue(f, values[f.id] ?? f.default));
    if (v !== "normal") out.push(`-modifier ${f.id} ${v}`);
  }
  if (cleanValue(VALHEIM_FIELDS[6], values.playerevents) === true) out.push("-setkey playerevents");
  return out.join(" ");
}

/** A preset overrides individual modifiers: list the modifiers that will be ignored. */
export function valheimOverridden(values: GenValues): string[] {
  if (cleanValue(VALHEIM_FIELDS[0], values.preset ?? "normal") === "normal") return [];
  return VALHEIM_FIELDS.slice(1, 6).filter((f) => String(cleanValue(f, values[f.id] ?? f.default)) !== "normal").map((f) => f.id);
}
